package com.bank.qa.classify;

// The distinct root-cause categories a mass failure can fall into.
enum Cause {
    PRODUCT_REGRESSION,   // genuine defect — raise bug, maybe roll back
    API_CONTRACT_CHANGE,  // schema/status changed — version + update or fix product
    CHANGED_LOCATORS,     // UI refactor — update page objects (product OK)
    AUTH_OR_ENV,          // login/env/base URL — fix config/secret (product OK)
    MISSING_TEST_DATA     // deploy reset data — restore seeding (product OK)
}
