package com.bank.qa.classify;

import java.util.*;
import java.util.logging.*;

public class FailureClassifyDemo {
    private static final Logger log = Logger.getLogger(FailureClassifyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new ClassifyLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // A batch of post-deploy failures with varied signatures.
        List<Failure> failures = List.of(
            new Failure("login.spec", "login failed: 401 unauthorized"),
            new Failure("dashboard.spec", "login failed: connection refused base url"),
            new Failure("transfer-ui.spec", "element not found: locator getByRole(button,Transfer)"),
            new Failure("accounts-api.spec", "schema mismatch: missing field transactionId"),
            new Failure("statement.spec", "no such account SAV2001 (not seeded)"),
            new Failure("transfer-amount.spec", "expected balance 950000 but was 900000")
        );

        FailureClassifier clf = new FailureClassifier();

        log.info("=== Classify post-deploy failures (DON'T assume one cause) ===");
        Map<Cause, List<String>> groups = clf.classifyAll(failures);
        groups.forEach((cause, tests) ->
            log.info(cause + " (" + tests.size() + "): " + tests + "  -> " + clf.action(cause)));

        boolean realRegression = groups.containsKey(Cause.PRODUCT_REGRESSION);
        log.info(realRegression
            ? "RESULT: at least one GENUINE product defect found -> escalate separately from test updates"
            : "RESULT: all failures are brittle-automation/env -> update tests/config, product OK");
    }
}

// ─── Would be in ClassifyLogFormatter.java in a real project ───
class ClassifyLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
